<template>
  <div class="cpf-page-stack">
    <section class="cpf-card">
      <div class="cpf-card-head"><h1>Feature Flag 운영</h1><span class="cpf-status warning">위험 조치 승인 필요</span></div>
      <p>Typed 평가, 검색·상세, 만료 Override, Kill Switch를 운영합니다. Flag 값은 목록·감사 화면에 원문으로 노출하지 않습니다.</p>
      <p v-if="error" class="cpf-error" role="alert">{{ error }}</p><p v-if="approvalNotice" class="cpf-status info" role="status">{{ approvalNotice }}</p>
      <div class="cpf-toolbar"><input v-model.trim="query" aria-label="Flag 검색" placeholder="Flag Key"><button @click="search">검색</button></div>
      <table class="cpf-table"><thead><tr><th>Flag</th><th>Source</th><th>Revision</th><th>Reason</th></tr></thead><tbody><tr v-for="row in rows" :key="row.flagKey" @click="selected=row"><td>{{ row.flagKey }}</td><td>{{ row.source }}</td><td>{{ row.revision }}</td><td>{{ row.reasonCode }}</td></tr><tr v-if="!rows.length"><td colspan="4">조회 결과가 없습니다.</td></tr></tbody></table>
    </section>
    <section class="cpf-card">
      <h2>Typed 평가</h2>
      <div class="cpf-form-grid"><label>Flag Key<input v-model.trim="evaluation.flagKey"></label><label>Type<select v-model="evaluation.valueType"><option>BOOLEAN</option><option>STRING</option><option>INTEGER</option><option>DECIMAL</option></select></label><label>Fallback<input v-model="evaluation.value"></label><label>Targeting Key<input v-model.trim="evaluation.targetingKey"></label></div>
      <button class="primary" :disabled="busy" @click="evaluate">평가</button><pre v-if="evaluated">{{ safeResult(evaluated) }}</pre>
    </section>
    <section class="cpf-card">
      <h2>Override 승인 요청</h2>
      <div class="cpf-form-grid"><label>Flag Key<input v-model.trim="override.flagKey"></label><label>Type<select v-model="override.valueType"><option>BOOLEAN</option><option>STRING</option><option>INTEGER</option><option>DECIMAL</option></select></label><label>Value<input v-model="override.value" type="password" autocomplete="off"></label><label>Expires At<input v-model="override.expiresAt" type="datetime-local"></label><label class="span-2">사유<input v-model.trim="override.reason"></label></div>
      <button class="primary" :disabled="busy || !canRequestOverride" @click="requestOverride">요청</button>
      <div class="cpf-form-grid"><label>Request ID<input v-model.trim="decision.requestId"></label><label>승인/회수 사유<input v-model.trim="decision.reason"></label></div>
      <div class="cpf-action-row"><button v-if="canApproveOverride" :disabled="busy" @click="approve">승인</button><button v-if="canRevokeOverride" class="danger" :disabled="busy" @click="revoke">회수</button></div>
    </section>
    <section class="cpf-card"><h2>Kill Switch</h2><div class="cpf-form-grid"><label>Flag Key<input v-model.trim="kill.flagKey"></label><label>상태<select v-model="kill.enabled"><option :value="true">활성</option><option :value="false">해제</option></select></label><label class="span-2">사유<input v-model.trim="kill.reason"></label></div><button v-if="canSetKillSwitch" class="danger" :disabled="busy" @click="setKill">승인 요청</button></section>
  </div>
</template>
<script lang="ts">
import { defineComponent } from "vue";
import { useAdmSessionStore } from "../../stores/admSessionStore";
import { admApprovalRequest, admFeatureFlagApproveOverride, admFeatureFlagEvaluate, admFeatureFlagFind, admFeatureFlagRequestOverride, admFeatureFlagRevokeOverride, admFeatureFlagSearch } from "../../generated/cpf-api";
type Row={flagKey:string;source:string;revision:number;reasonCode:string;value?:unknown};
export default defineComponent({name:"FeatureFlagsPage",setup(){const session=useAdmSessionStore();return{session};},computed:{canRequestOverride(){return this.session.hasButton("FEATURE_FLAG_OVERRIDE_REQUEST");},canApproveOverride(){return this.session.hasButton("FEATURE_FLAG_OVERRIDE_APPROVE");},canRevokeOverride(){return this.session.hasButton("FEATURE_FLAG_OVERRIDE_REVOKE");},canSetKillSwitch(){return this.session.hasButton("FEATURE_FLAG_KILL_SWITCH");}},data(){return{busy:false,error:"",approvalNotice:"",query:"",rows:[] as Row[],selected:null as Row|null,evaluated:null as Row|null,evaluation:{flagKey:"",valueType:"BOOLEAN",value:"false",targetingKey:"operator-preview"},override:{flagKey:"",valueType:"BOOLEAN",value:"false",expiresAt:"",reason:""},decision:{requestId:"",reason:""},kill:{flagKey:"",enabled:true,reason:""}}},mounted(){void this.search();},methods:{async run<T>(action:()=>Promise<T>){this.busy=true;this.error="";try{return await action();}catch(e){this.error=e instanceof Error?e.message:String(e);return undefined;}finally{this.busy=false;}},async search(){const result=await this.run(()=>admFeatureFlagSearch<Row[]>({query:{query:this.query,page:0,size:100}}));this.rows=result??[];},async evaluate(){this.evaluated=(await this.run(()=>admFeatureFlagEvaluate<Row>({data:{...this.evaluation,attributes:{channel:"ADM"}}})))??null;},async requestOverride(){if(!this.canRequestOverride)throw new Error("FEATURE_FLAG_OVERRIDE_REQUEST 권한이 없습니다.");const result=await this.run(()=>admFeatureFlagRequestOverride<{requestId:string}>({data:{...this.override,expiresAt:new Date(this.override.expiresAt).toISOString()}}));if(result)this.decision.requestId=result.requestId;this.override.value="";},async approve(){if(!this.canApproveOverride)throw new Error("FEATURE_FLAG_OVERRIDE_APPROVE 권한이 없습니다.");await this.run(()=>admFeatureFlagApproveOverride({path:{requestId:this.decision.requestId},data:{reason:this.decision.reason},headers:{"X-CPF-Risk-Confirmed":"confirmed"}}));await this.search();},async revoke(){if(!this.canRevokeOverride)throw new Error("FEATURE_FLAG_OVERRIDE_REVOKE 권한이 없습니다.");await this.run(()=>admFeatureFlagRevokeOverride({path:{requestId:this.decision.requestId},data:{reason:this.decision.reason},headers:{"X-CPF-Risk-Confirmed":"confirmed"}}));await this.search();},async setKill(){if(!this.canSetKillSwitch)throw new Error("FEATURE_FLAG_KILL_SWITCH 권한이 없습니다.");if(!this.kill.flagKey.trim()||this.kill.reason.trim().length<8)throw new Error("Flag Key와 8자 이상의 감사 사유가 필요합니다.");const current=await this.run(()=>admFeatureFlagFind<Row>({path:{flagKey:this.kill.flagKey.trim()}}));if(!current)return;const requestKey=`feature-kill-${this.kill.flagKey.slice(0,32)}-${crypto.randomUUID()}`;const result=await this.run(()=>admApprovalRequest<Record<string,unknown>>({data:{requestKey,actionType:"FEATURE_FLAG_KILL_SWITCH",ownerModule:"CPF-PLATFORM-OPERATIONS",ownerCommand:"FEATURE_FLAG_KILL_SWITCH",targetType:"FEATURE_FLAG",targetId:this.kill.flagKey.trim(),payloadSnapshot:JSON.stringify({enabled:this.kill.enabled,expectedRevision:Number(current.revision)}),reason:this.kill.reason.trim()}}));if(result){const id=String(result.approvalRequestId??result.requestId??result.id??"");this.approvalNotice=id?`Kill Switch 승인 요청 ${id}가 생성되었습니다. 독립 승인 후 승인 화면에서 실행하세요.`:"Kill Switch 승인 요청이 생성되었습니다.";}},safeResult(row:Row){return JSON.stringify({flagKey:row.flagKey,source:row.source,revision:row.revision,reasonCode:row.reasonCode},null,2);}}});
</script>
